#include <spanstream>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    char buffer[16] = "42";
    std::ispanstream stream{std::span<char>{buffer}};
    int value{};
    stream >> value;
    assert(value == 42);
    assert(stream.rdbuf() != nullptr);
    char backup[16]{};
    std::ispanstream other{std::span<char>{backup}};
    other = std::move(stream);
    other.swap(stream);
    std::swap(other, stream);
    std::cout << "Checks passed\n";
}
